This script doesn't actually implement the screen sharing functionality itself. It's just a basic server that generates a unique link and keeps track of those links for 5 minutes.

Please note that you need to install Flask if you haven't done so already. You can do this by running `pip install flask` in your terminal.

```python
from flask import Flask, request, jsonify
from flask_caching import Cache
import time
import random
import string

app = Flask(__name__)
cache = Cache(app, config={})

# Dictionary to store shared links and their expiration times
shared_links = {}

@app.route('/shared', methods=['POST'])
def share():
    url = request.json['url']
    if url:
        # Generate a unique link and store it in the cache
        link = ''.join(random.choices(string.ascii_letters + string.digits, k=20))
        shared_links[link] = time.time() + 300  # 5 minutes
        return jsonify({'link': link})

@app.route('/link', methods=['GET'])
def get_link():
    link = request.args.get('link')
    if link:
        if link in shared_links:
            if time.time() < shared_links[link]:
                return jsonify({'success': True})
            else:
                del shared_links[link]
        return jsonify({'success': False})

if __name__ == '__main__':
    app.run(debug=True)
```

